22	/// A plain (non-mocktail) fake — same rationale as `vault_lock_screen_test.
23	/// dart`'s own `_FakeVaultRepository`: this suite needs a scriptable
24	/// `setBiometricEnabled()` result plus a real stream the cubit actually
25	/// subscribes to, which a mocktail stub can't give as naturally.
26	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
27	  bool _value = true;
28	  final _controller = StreamController<bool>.broadcast();
29	
30	  /// The next `setBiometricEnabled()` call's own result — defaults to a
31	  /// failure so a test must opt in to the success path explicitly.
32	  Either<Failure, Unit> setBiometricEnabledResult = left(
33	    const Failure.malformedResponse(message: 'fake: not configured'),
34	  );
35	
36	  int setBiometricEnabledCallCount = 0;
37	
38	  // spec-8-3 — a scriptable profile-name slice, same rationale
39	  // [setBiometricEnabledResult] already gives for the toggle: a test must
40	  // opt in to a non-default [currentDisplayName]/[currentEmail] or a
41	  // [setDisplayNameResult] success explicitly.
42	  @override
43	  String currentDisplayName = '';
44	  @override
45	  String currentEmail = '';
46	  Either<Failure, Unit> setDisplayNameResult = left(
47	    const Failure.malformedResponse(message: 'fake: not configured'),
48	  );
49	  int setDisplayNameCallCount = 0;
50	  String? lastSetDisplayNameArg;
51	
52	  /// Lets a test hold `setDisplayName()` unresolved, to observe
53	  /// `state.isSavingName` mid-flight — same rationale
54	  /// `account_settings_screen_test.dart`'s own `setBiometricEnabledGate`
55	  /// already gives for the toggle.
56	  Completer<void>? setDisplayNameGate;
57	
58	  /// Review finding — mirrors `AccountSettingsRepositoryImpl.
59	  /// setDisplayName`'s own "echo wins" behavior: on success,
60	  /// `currentDisplayName` is set to this value (defaulting to whatever was
61	  /// actually sent) rather than always just echoing the argument back
62	  /// unchanged. Lets a test prove the cubit reads the repository's own
63	  /// post-save value rather than assuming the server stored exactly what
64	  /// was sent.
65	  String? setDisplayNameEchoedNameOverride;
66	
67	  @override
68	  Future<Either<Failure, Unit>> setDisplayName(String name) async {
69	    setDisplayNameCallCount += 1;
70	    lastSetDisplayNameArg = name;
71	    final gate = setDisplayNameGate;
72	    if (gate != null) {
73	      await gate.future;
74	    }
75	    if (setDisplayNameResult.isRight()) {
76	      currentDisplayName = setDisplayNameEchoedNameOverride ?? name;
77	    }
78	    return setDisplayNameResult;
79	  }
80	
81	  @override
82	  bool get currentBiometricEnabled => _value;
83	
84	  @override
85	  Stream<bool> get biometricEnabledStream {
86	    return Stream<bool>.multi((controller) {
87	      controller.add(_value);
88	      final subscription = _controller.stream.listen(
89	        controller.add,
90	        onError: controller.addError,
91	        onDone: controller.close,
92	      );
93	      controller.onCancel = subscription.cancel;
94	    }, isBroadcast: true);
95	  }
96	
97	  @override
98	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
99	
100	  @override
101	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
102	    setBiometricEnabledCallCount += 1;
103	    final previous = _value;
104	    _emit(enabled);
105	    final result = setBiometricEnabledResult;
106	    if (result.isLeft()) {
107	      _emit(previous);
108	    }
109	    return result;
110	  }
111	
112	  // Story 8.5 — scriptable like [setBiometricEnabledResult]/
113	  // [setDisplayNameResult] above: defaults to a failure so a test must
114	  // opt in to the success path explicitly.
115	  Either<Failure, Unit> deleteAccountResult = left(
116	    const Failure.malformedResponse(message: 'fake: not configured'),
117	  );
118	
119	  int deleteAccountCallCount = 0;
120	
121	  /// Lets a test hold `deleteAccount()` unresolved, to observe
122	  /// `state.isDeletingAccount` mid-flight — same rationale
123	  /// [setDisplayNameGate] already gives for name saves.
124	  Completer<void>? deleteAccountGate;
125	
126	  @override
127	  Future<Either<Failure, Unit>> deleteAccount() async {
128	    deleteAccountCallCount += 1;
129	    final gate = deleteAccountGate;
130	    if (gate != null) {
131	      await gate.future;
132	    }
133	    return deleteAccountResult;
134	  }
135	
136	  @override
137	  Future<void> dispose() => _controller.close();
138	
139	  void _emit(bool value) {
140	    _value = value;
141	    _controller.add(value);
142	  }
143	}
