325	Future<List<AccountSettingsState>> _emittedDuring(
326	  AccountSettingsCubit cubit,
327	  Future<void> Function() act,
328	) async {
329	  final emitted = <AccountSettingsState>[];
330	  final subscription = cubit.stream.listen(emitted.add);
331	  await act();
332	  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
333	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
334	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
335	  // several microtask hops deep — one `Duration.zero` delay only guarantees
336	  // draining one hop, leaving a later hop's delivery to land after this
337	  // helper already returned.
338	  await pumpEventQueue();
339	  await subscription.cancel();
340	  return emitted;
341	}
