343	void main() {
344	  late _FakeAccountSettingsRepository fakeRepository;
345	  late _FakeSessionRepository fakeSessionRepository;
346	  late _FakeVaultRepository fakeVaultRepository;
347	  late _FakeEntriesRepository fakeEntriesRepository;
348	  late _FakeChatRepository fakeChatRepository;
349	
350	  setUp(() {
351	    fakeRepository = _FakeAccountSettingsRepository();
352	    fakeSessionRepository = _FakeSessionRepository();
353	    fakeVaultRepository = _FakeVaultRepository();
354	    fakeEntriesRepository = _FakeEntriesRepository();
355	    fakeChatRepository = _FakeChatRepository();
356	  });
357	
358	  /// Story 8.4 — every pre-existing test in this file only exercises the
359	  /// biometric toggle / profile-name slices, never [AccountSettingsCubit.
360	  /// logout], so the widened constructor's 4 new deps are passed through
361	  /// this one helper rather than repeating them at each of this file's
362	  /// pre-existing 16 call sites.
363	  AccountSettingsCubit buildCubit() => AccountSettingsCubit(
364	    fakeRepository,
365	    fakeSessionRepository,
366	    fakeVaultRepository,
367	    fakeEntriesRepository,
368	    fakeChatRepository,
369	  );
370	
371	  group('initial state', () {
372	    test('mirrors currentBiometricEnabled (true) at construction', () async {
373	      final cubit = buildCubit();
374	
375	      expect(cubit.state.biometricEnabled, isTrue);
376	      expect(cubit.state.errorMessage, isNull);
377	      await cubit.close();
378	    });
379	
380	    test('mirrors a false currentBiometricEnabled (e.g. already fetched '
381	        'before the screen opened)', () async {
382	      fakeRepository._emit(false);
383	      final cubit = buildCubit();
384	
385	      expect(cubit.state.biometricEnabled, isFalse);
386	      await cubit.close();
387	    });
388	  });
