390	  group('toggleBiometric() — success', () {
391	    test('flips to the new value and clears any prior error, calling the '
392	        'repository with exactly the requested value', () async {
393	      fakeRepository.setBiometricEnabledResult = right(unit);
394	      final cubit = buildCubit();
395	
396	      final emitted = await _emittedDuring(
397	        cubit,
398	        () => cubit.toggleBiometric(false),
399	      );
400	
401	      expect(emitted.last.biometricEnabled, isFalse);
402	      expect(emitted.last.errorMessage, isNull);
403	      expect(fakeRepository.setBiometricEnabledCallCount, 1);
404	      await cubit.close();
405	    });
406	  });
407	
408	  group('toggleBiometric() — failure', () {
409	    test('the switch reverts (mirrored from the repository\'s own revert) '
410	        'and the Failure\'s message is surfaced', () async {
411	      fakeRepository.setBiometricEnabledResult = left(
412	        const Failure.networkTimeout(message: 'Sem conexão'),
413	      );
414	      final cubit = buildCubit();
415	      // Drains the constructor's own subscription-replay of the current
416	      // value (Stream.multi's replay goes through its own forwarding
417	      // subscription, several microtask hops deep) before the capture
418	      // window below starts — otherwise that replay (allowed through by
419	      // Cubit's own "first emit always goes through" rule) can land
420	      // mid-capture as a spurious extra entry. `pumpEventQueue()` drains
421	      // repeatedly until the queue is empty, rather than a single
422	      // `Future.delayed(Duration.zero)` which only guarantees one hop.
423	      await pumpEventQueue();
424	
425	      final emitted = await _emittedDuring(
426	        cubit,
427	        () => cubit.toggleBiometric(false),
428	      );
429	
430	      // Two independent emission paths feed `emitted` here: the
431	      // `biometricEnabled` flip/revert mirrors the repository's own stream
432	      // (several `Stream.multi` forwarding hops deep), while the
433	      // `errorMessage` update is `toggleBiometric()`'s own direct `emit()`
434	      // (one hop). Their relative *order* isn't guaranteed by either path's
435	      // own contract, so asserting an exact sequence would pin an
436	      // implementation accident, not a behavior the spec requires — what
437	      // the I/O matrix actually requires (and what's asserted below) is
438	      // that the optimistic flip to `false` was visible at some point, and
439	      // that the settled end state reverted to `true` with the `Failure`'s
440	      // message surfaced.
441	      expect(emitted.map((s) => s.biometricEnabled), contains(false));
442	      expect(emitted.last.biometricEnabled, isTrue);
443	      expect(emitted.last.errorMessage, 'Sem conexão');
444	      expect(cubit.state.biometricEnabled, isTrue);
445	      expect(cubit.state.errorMessage, 'Sem conexão');
446	      await cubit.close();
447	    });
448	
449	    test(
450	      'a later successful toggle clears the previous error message',
451	      () async {
452	        fakeRepository.setBiometricEnabledResult = left(
453	          const Failure.networkTimeout(message: 'Sem conexão'),
454	        );
455	        final cubit = buildCubit();
456	        await cubit.toggleBiometric(false);
457	        // `toggleBiometric()`'s own await only guarantees its direct
458	        // `setBiometricEnabled()` Future resolved — the `biometricEnabled`
459	        // mirror it emits travels back through the repository's
460	        // `Stream.multi` forwarding subscription, several microtask hops
461	        // behind that Future; drain those before asserting on `cubit.state`
462	        // (same rationale as `_emittedDuring`'s own `pumpEventQueue()`).
463	        await pumpEventQueue();
464	        expect(cubit.state.errorMessage, 'Sem conexão');
465	
466	        fakeRepository.setBiometricEnabledResult = right(unit);
467	        await cubit.toggleBiometric(true);
468	        await pumpEventQueue();
469	
470	        expect(cubit.state.errorMessage, isNull);
471	        expect(cubit.state.biometricEnabled, isTrue);
472	        await cubit.close();
473	      },
474	    );
475	  });
476	
