507	
508	  group('updateNameDraft()', () {
509	    test(
510	      'updates nameDraft without touching isEditingName/displayName',
511	      () async {
512	        final cubit = buildCubit();
513	        cubit.startEditingName();
514	
515	        cubit.updateNameDraft('Novo Nome');
