524	
525	  group('confirmEditingName() — empty/unchanged draft', () {
526	    test('an unchanged draft reverts immediately, no PATCH sent (I/O '
527	        'matrix)', () async {
528	      fakeRepository.currentDisplayName = 'Ana Silva';
529	      final cubit = buildCubit();
530	      cubit.startEditingName();
531	
532	      await cubit.confirmEditingName();
533	
534	      expect(cubit.state.isEditingName, isFalse);
535	      expect(cubit.state.displayName, 'Ana Silva');
536	      expect(fakeRepository.setDisplayNameCallCount, 0);
537	      await cubit.close();
538	    });
539	
540	    test('an all-whitespace (trims to empty) draft reverts immediately, no '
541	        'PATCH sent', () async {
542	      fakeRepository.currentDisplayName = 'Ana Silva';
543	      final cubit = buildCubit();
544	      cubit.startEditingName();
545	      cubit.updateNameDraft('   ');
546	
547	      await cubit.confirmEditingName();
548	
549	      expect(cubit.state.isEditingName, isFalse);
550	      expect(cubit.state.displayName, 'Ana Silva');
551	      expect(fakeRepository.setDisplayNameCallCount, 0);
552	      await cubit.close();
553	    });
554	  });
555	
556	  group('confirmEditingName() — changed non-empty draft, success', () {
557	    test('saves (trimmed), shows a saving indicator mid-flight, then '
558	        'reverts to display mode with the new name (I/O matrix)', () async {
559	      fakeRepository.currentDisplayName = 'Ana Silva';
560	      fakeRepository.setDisplayNameResult = right(unit);
561	      fakeRepository.setDisplayNameGate = Completer<void>();
562	      final cubit = buildCubit();
563	      cubit.startEditingName();
564	      cubit.updateNameDraft('  Nome Novo  ');
565	
566	      final confirmFuture = cubit.confirmEditingName();
567	      await Future<void>.delayed(Duration.zero);
568	      expect(cubit.state.isSavingName, isTrue);
569	      expect(cubit.state.isEditingName, isTrue);
570	
571	      fakeRepository.setDisplayNameGate!.complete();
572	      await confirmFuture;
573	
574	      expect(cubit.state.isSavingName, isFalse);
575	      expect(cubit.state.isEditingName, isFalse);
576	      expect(cubit.state.displayName, 'Nome Novo');
577	      expect(cubit.state.nameErrorMessage, isNull);
578	      expect(fakeRepository.lastSetDisplayNameArg, 'Nome Novo');
579	      await cubit.close();
580	    });
581	
582	    test(
583	      // Review finding: the success branch used to emit the locally-sent,
584	      // merely-trimmed draft instead of re-reading the repository's own
585	      // post-save value — defeating `AccountSettingsRepositoryImpl.
586	      // setDisplayName`'s own code-review patch, which sets
587	      // `currentDisplayName` from the response's echoed value so any
588	      // backend-side normalization (trimming, casing, etc.) is reflected
589	      // locally. This proves the cubit now shows that echoed value, not
590	      // the locally-sent one.
591	      'shows the repository\'s own echoed name on success, not the '
592	      'locally-sent one, when the server normalizes it differently',
593	      () async {
594	        fakeRepository.currentDisplayName = 'Ana Silva';
595	        fakeRepository.setDisplayNameResult = right(unit);
596	        fakeRepository.setDisplayNameEchoedNameOverride = 'Nome Novo (Servidor)';
597	        final cubit = buildCubit();
598	        cubit.startEditingName();
599	        cubit.updateNameDraft('Nome Novo');
600	
601	        await cubit.confirmEditingName();
602	
603	        expect(fakeRepository.lastSetDisplayNameArg, 'Nome Novo');
604	        expect(cubit.state.displayName, 'Nome Novo (Servidor)');
605	        await cubit.close();
606	      },
607	    );
608	  });
609	
610	  group('confirmEditingName() — failure', () {
