25	/// Same shape as `dashboard_flow_e2e_test.dart`'s/`export_flow_e2e_test.
26	/// dart`'s own fake — only the transport boundary is faked, everything
27	/// above it (URL building, both real interceptors, `ApiClient`'s mapping,
28	/// `AccountSettingsDto`'s decode) is the genuine production wiring.
29	class _FakeHttpClientAdapter implements HttpClientAdapter {
30	  final List<RequestOptions> requests = [];
31	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
32	
33	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
34	    _queue.add((statusCode: statusCode, body: body));
35	  }
36	
37	  void queueErrorResponse(String code, String message) {
38	    final status = switch (code) {
39	      'VALIDATION_ERROR' => 400,
40	      'NETWORK_TIMEOUT' => 504,
41	      _ => 500,
42	    };
43	    queueJsonResponse(status, {
44	      'code': code,
45	      'message': message,
46	      'retryable': RetryInterceptor.retryableCodes.contains(code),
47	    });
48	  }
49	
50	  @override
51	  Future<ResponseBody> fetch(
52	    RequestOptions options,
53	    Stream<Uint8List>? requestStream,
54	    Future<void>? cancelFuture,
55	  ) async {
56	    requests.add(options);
57	    if (_queue.isEmpty) {
58	      throw StateError(
59	        'No queued response for ${options.method} ${options.path}',
60	      );
61	    }
62	    final next = _queue.removeAt(0);
63	    return ResponseBody.fromString(
64	      jsonEncode(next.body),
65	      next.statusCode,
66	      headers: {
67	        Headers.contentTypeHeader: [Headers.jsonContentType],
68	      },
69	    );
70	  }
71	
72	  @override
73	  void close({bool force = false}) {}
74	}
