126	  const secureStorageChannel = MethodChannel(
127	    'plugins.it_nomads.com/flutter_secure_storage',
128	  );
129	  final fakeNativeStorage = <String, String>{};
130	
131	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
132	    final args = call.arguments as Map<dynamic, dynamic>;
133	    switch (call.method) {
134	      case 'write':
135	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
136	        return null;
137	      case 'read':
138	        return fakeNativeStorage[args['key'] as String];
139	      case 'delete':
140	        fakeNativeStorage.remove(args['key'] as String);
141	        return null;
142	      case 'containsKey':
143	        return fakeNativeStorage.containsKey(args['key'] as String);
144	      default:
145	        return null;
146	    }
147	  }
148	
149	  late FakePathProviderPlatform fakePathProvider;
150	  late _FakeHttpClientAdapter adapter;
151	
152	  setUp(() async {
153	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
154	        .setMockMethodCallHandler(
155	          secureStorageChannel,
