157	        );
158	    // setupCoreDependencies() also wires the entries feature, which opens a
159	    // Hive box (via Hive.initFlutter()) eagerly at registration time, not
160	    // lazily on first resolution — same rationale `dashboard_flow_e2e_test.
161	    // dart`'s own setUp already gives, even though this suite never touches
162	    // entries itself.
163	    fakePathProvider = FakePathProviderPlatform();
164	    PathProviderPlatform.instance = fakePathProvider;
165	
166	    await resetCoreDependencies();
167	    await setupCoreDependencies();
168	
169	    adapter = _FakeHttpClientAdapter();
170	    sl<Dio>().httpClientAdapter = adapter;
171	
172	    // account-settings-update is a bearer-required operation — seed a user
173	    // access token through the real AccessTokenProvider so the real header
174	    // interceptor has one to send.
175	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
176	  });
