39	/// Same plain (non-mocktail) fake shape as
40	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
41	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
42	/// real stream the cubit (built from this fake, not mocked) actually
43	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
44	/// a `Stream.multi` replay wrapper (unlike the production repository) —
45	/// `AccountSettingsCubit`'s own constructor already reads
46	/// [currentBiometricEnabled] directly for its initial state, so no replay
47	/// machinery is needed for a fake with exactly one subscriber.
48	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
49	  bool _value = true;
50	  final _controller = StreamController<bool>.broadcast();
51	
52	  /// The next `setBiometricEnabled()` call's own result — defaults to a
53	  /// failure so a test must opt in to the success path explicitly, same
54	  /// convention as the cubit-level fake.
55	  Either<Failure, Unit> setBiometricEnabledResult = left(
56	    const Failure.malformedResponse(message: 'fake: not configured'),
57	  );
58	
59	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
60	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
61	  /// disable itself while a toggle is in flight).
62	  Completer<void>? setBiometricEnabledGate;
63	
64	  // spec-8-3 — same "configurable before the screen is pumped" convention
65	  // `_FakeDashboardRepository`'s own fields already use.
66	  @override
67	  String currentDisplayName = '';
68	
69	  @override
70	  String currentEmail = '';
71	
72	  /// The next `setDisplayName()` call's own result — defaults to a failure
73	  /// so a test must opt in to the success path explicitly, same convention
74	  /// as [setBiometricEnabledResult].
75	  Either<Failure, Unit> setDisplayNameResult = left(
76	    const Failure.malformedResponse(message: 'fake: not configured'),
77	  );
78	
79	  /// Lets a test hold `setDisplayName()` unresolved, to observe
80	  /// `state.isSavingName` mid-flight — same rationale
81	  /// [setBiometricEnabledGate] already gives for the toggle.
82	  Completer<void>? setDisplayNameGate;
83	
84	  int setDisplayNameCallCount = 0;
85	
86	  /// Review finding — mirrors `AccountSettingsRepositoryImpl.
87	  /// setDisplayName`'s own "echo wins" behavior: on success,
88	  /// `currentDisplayName` is set to this value (defaulting to whatever
89	  /// was actually sent) rather than always just echoing the argument
90	  /// back unchanged.
91	  String? setDisplayNameEchoedNameOverride;
92	
93	  @override
94	  Future<Either<Failure, Unit>> setDisplayName(String name) async {
95	    setDisplayNameCallCount += 1;
96	    final gate = setDisplayNameGate;
97	    if (gate != null) {
98	      await gate.future;
99	    }
100	    if (setDisplayNameResult.isRight()) {
101	      currentDisplayName = setDisplayNameEchoedNameOverride ?? name;
102	    }
103	    return setDisplayNameResult;
104	  }
105	
106	  @override
107	  bool get currentBiometricEnabled => _value;
108	
109	  @override
110	  Stream<bool> get biometricEnabledStream => _controller.stream;
111	
112	  @override
113	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
114	
115	  @override
116	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
117	    final gate = setBiometricEnabledGate;
118	    if (gate != null) {
119	      await gate.future;
120	    }
121	    final previous = _value;
122	    _emit(enabled);
123	    final result = setBiometricEnabledResult;
124	    if (result.isLeft()) {
125	      _emit(previous);
126	    }
127	    return result;
128	  }
